SELECT 'directory-additions-20261027',x.entry_key,x.content_hash,x.payload FROM jsonb_to_recordset($new$[{"content_hash":"299ebed86df3569a84b04c12b86984a441ffd2e60194dcd9630dc943c6774071","entry_key":"c2db8f35aaeaaf7cb7aaef8f38b60cf39fc7f701931fc9918e655ec25b8dede4","payload":"{\"additional\":\"https://www.choiceimagingfw.com/\\nhttps://www.choiceimagingfw.com/mri-center-fort-wayne-indiana\\nhttps://www.choiceimagingfw.com/schedule-form\\nhttps://irp.cdn-website.com/b4743f6b/files/uploaded/ChoiceImagingRXpadfront2025.pdf\",\"area\":\"Fort Wayne\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"1850 E. Dupont Road, Fort Wayne, IN 46825. MRI, CT, ultrasound, X-ray and DEXA verified. Phone 260-422-1491.\",\"ct\":\"$275 without contrast; $400 with contrast. Separate without-and-with rate and combined-region pricing are not specified.\",\"entity\":\"Independent diagnostic imaging facility\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"$450 without contrast; $550 with contrast. Exact body-part count and with-only versus without-and-with protocol need confirmation.\",\"name\":\"Choice Imaging \\u2014 Fort Wayne\",\"notes\":\"Cash/self-pay table is explicitly for patients not using insurance. Radiologist interpretation is included; no separate facility-fee statement is published. Accepts cash, check, Visa, Mastercard and Discover; full-prepayment timing is not specified. Referring-physician signature and diagnosis are requested on the order form. Standard diagnostic MRI/MRA and CT protocols are offered; MRI arthrograms are not currently performed on the services page. Do not apply standard rates to separately marketed elective full-body/torso scans or assume a multi-region package. The approximate $100 contrast add-on in the insurance section is not the cash CT rule: the explicit self-pay CT-with-contrast price is $400. Pricing page is undated; checked October 19, 2026.\",\"other\":\"Ultrasound $250; X-ray $85 for one body part (2\\u20133 views), $45 each additional body part, full spine (6 views) $175; DEXA bone-density screening $100. Elective body-composition packages are separate.\",\"row\":\"157\",\"source\":\"https://www.choiceimagingfw.com/mri-insurance-fort-wayne-indiana\",\"states\":\"IN\"}"},{"content_hash":"bcd69a57fafa8b2f987da261dcd3f2ff9701803790bd82cd5770362db9c24cab","entry_key":"2cf089512f28ee22668c60cb745d3156e28a729205af34ca34f2dfa13ff8d4b4","payload":"{\"additional\":\"https://www.myssmi.com/locations\\nhttps://www.myssmi.com/about\\nhttps://www.myssmi.com/resources/patient-referral\\nhttps://storage.googleapis.com/treatspace-prod-media/pracf/u-2740/SSMI_Order_Form.pdf\\nhttps://www.myssmi.com/blog/smart-scan-offers-affordable-mris-in-eau-claire-and-wausau\",\"area\":\"Eau Claire\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"3004 Golf Road, Suite 101A, Eau Claire, WI 54701. Diagnostic MRI verified. Phone 855-694-3300.\",\"ct\":\"Operator advertises CT, but Eau Claire availability and cash price were not verified\",\"entity\":\"Independent outpatient imaging operator / individual center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"$650 without contrast for most exams; $850 with and without contrast. Exact exam eligibility must be confirmed.\",\"name\":\"Smart Scan Medical Imaging \\u2014 Eau Claire Center\",\"notes\":\"Pricing page explicitly covers Eau Claire and three other Wisconsin markets. Price includes MRI scan and radiologist report. Discount requires full payment at time of service; not available for deferred/future payment arrangements. Site warns third-party intermediaries can raise cost. No separate facility fee is stated, but the page does not enumerate every included ancillary item. The $650 rate says most exams and does not publish a complete eligible-CPT list, so obtain the ordered-exam total. Provider referral page supplies a physician-signed diagnostic order form. Whole-body/Ezra screening is separately marketed and should not be assigned these diagnostic rates. Main pricing page is undated; a corroborating operator article was last updated September 13, 2026. Checked October 19, 2026.\",\"other\":\"Operator advertises ultrasound, but Eau Claire availability and cash price were not verified\",\"row\":\"158\",\"source\":\"https://www.myssmi.com/resources/pricing-and-payments\",\"states\":\"WI\"}"},{"content_hash":"21a78f36a570282e9aa18c779914dca94edefdae8cfffc801251bea54a4a2450","entry_key":"00fcc9c750d404b1fe41020cdea5b512a8694b4dbe59c5ccb6da9ba24a2cb6fd","payload":"{\"additional\":\"https://www.orthoillinois.com/locations/rockford-roxbury-imaging-center/\\nhttps://www.orthoillinois.com/mri-imaging/\\nhttps://www.orthoillinois.com/employers/bundle-pricing-for-self-funded-employers/\",\"area\":\"Rockford\",\"category\":\"Quote required\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"324 Roxbury Road, Rockford, IL 61107. Musculoskeletal MRI verified. Phone 815-398-9491.\",\"ct\":\"Not verified at this specific imaging center\",\"entity\":\"Orthopedic practice imaging center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Operator's musculoskeletal MRI bundle menu: $495 without contrast; $775 with contrast. Confirm Roxbury eligibility before treating as a site price.\",\"name\":\"OrthoIllinois \\u2014 Rockford Roxbury Imaging Center\",\"notes\":\"Site admits existing patients and the public with a physician's medical order. Bundle menu includes scan, orthopedic-specialized radiologist read and report; an explanatory follow-up visit is included only when ordered by an OrthoIllinois physician. Self-pay patients and employees of self-funded organizations are eligible only when no insurance claim is filed; full cash/credit-card payment is required before service. Crucial applicability ambiguity: the MRI bundle page limits bundles to OrthoIllinois-owned ancillary surgery centers, while listing Roxbury and four other clinic addresses. The Roxbury MRI page confirms MRI/self-pay access but does not restate the dollar bundle. Thus the operator menu is verified, but Roxbury bundle applicability requires confirmation. With-contrast wording does not distinguish with-only from without-and-with. No additional facility fee is separately identified. Pages are undated; checked October 19, 2026.\",\"other\":\"No other site-specific cash imaging prices verified\",\"row\":\"159\",\"source\":\"https://www.orthoillinois.com/bundled-pricing/mri/\",\"states\":\"IL\"}"},{"content_hash":"1b218d58dc125c262730209a20ee9edbaa3a80014c3b3fc39dfe1da68169d600","entry_key":"b50b4e87b3a3f7efdef1cc497e278f703c9b8f12cf83aabdea8c8898f595b987","payload":"{\"additional\":\"https://www.signaturemedicalgroup.com/locations/signature-orthopedics-south-county/\",\"area\":\"St. Louis\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"12639 Old Tesson Road, Suites 100 and 115, St. Louis, MO 63128. South County only for published self-pay MRI offer. Phone 314-849-0311.\",\"ct\":\"Not listed at this site\",\"entity\":\"Physician-owned orthopedic practice imaging facility\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Schedule effective August 1, 2024: any MRI without contrast $450; with and without contrast $700, except brain CPT 70553 $675; MRI arthrogram $675. Reconfirm current price.\",\"name\":\"Signature Orthopedics \\u2014 South County\",\"notes\":\"Official self-pay page expressly assigns the offer to South County and labels prices all-inclusive, including radiologist reading and contrast. No additional facility charge is identified. Published schedule is effective August 1, 2024 and remains on the official page when checked October 19, 2026; reconfirm current applicability rather than treating the dated amount as a current quote. Body-region count, self-pay eligibility restrictions, payment timing/methods, physician-order requirements, sedation and related ancillary charges are not explained in this offer. Do not infer that the offer applies to other Signature locations. The location page verifies MRI and X-ray on site.\",\"other\":\"On-site X-ray verified; cash price not published on reviewed pages\",\"row\":\"160\",\"source\":\"https://www.signaturemedicalgroup.com/patient-resources/pay-my-bill/imaging-selfpay/\",\"states\":\"MO\"}"},{"content_hash":"b93112f08471de5ea2fdbed81f36ad451ab6e05553e2f33b0fee3719fb57f40d","entry_key":"9219ccbad40ac835859db18f09508123841dd6c03dab9a268be5050250efec72","payload":"{\"additional\":\"https://hitchcock.md/services/radiology/ultrasound/\",\"area\":\"Hixson\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"5104 Hixson Pike, Hixson, TN 37343; Chattanooga area\",\"ct\":\"Without contrast $350; with contrast $475; with and without contrast $475; CTA single region $400, second-region add-on $100; ultra-low-dose diagnostic chest CT $150; low-dose lung cancer screening $250; cardiac calcium score (noncontrast) $100\",\"entity\":\"Direct operator\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Not offered on reviewed imaging menu\",\"name\":\"Hitchcock Direct Imaging \\u2014 Hixson\",\"notes\":\"Published prices expressly include examination, facility services, applicable contrast for the ordered study, board-certified radiologist interpretation, final report and digital images on request; no separate facility or radiologist bill. Confirm exact exam/body-region scope and any bilateral add-on. Licensed-provider order required for every imaging study; outside providers accepted and no Hitchcock membership required. CT/ultrasound scheduled after order received; X-ray walk-ins after order received. Self-pay only, including insured patients; insurance not billed. Payment at service; HSA/FSA accepted. Confirm lung-screening eligibility with ordering provider. Undated current provider menu checked October 19, 2026.\",\"other\":\"Ultrasound: General, OB/GYN or vascular $160; bilateral add-on $50 when applicable; ABI ultrasound $160\\nX-ray: $40; bilateral add-on $20 when applicable\",\"row\":\"161\",\"source\":\"https://hitchcock.md/services/radiology/\",\"states\":\"TN\"}"},{"content_hash":"458e0d9d3e6858d59b93b0b624896ec7238ad1ac4200fb55025a449429c12168","entry_key":"2f435774d1b1eeb7882eaed73a7deb068f17ba79f38c8eaafb6401b32638e912","payload":"{\"additional\":\"https://cpaimaging.com/insurance-pricing/\\nhttps://cpaimaging.com/services/ct-scanning/\\nhttps://cpaimaging.com/services/ultrasound-imaging/\",\"area\":\"New York (Manhattan)\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"110 E 60th St, Lower Level, New York, NY 10022\",\"ct\":\"Diagnostic CT offered; exact self-pay amount not published on reviewed CT service page\",\"entity\":\"Direct operator\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Brain/neuro without contrast $1,050; without and with contrast $1,380. Spine $630 (base menu does not specify contrast), without and with $750. MSK/extremity $600 (base contrast unspecified), without and with $720. Abdomen/pelvis menu label $1,050 (base contrast unspecified), without and with $1,680; confirm whether abdomen and pelvis are separate regions. Advanced neuro $1,400; advanced neuro without and with $1,680\",\"name\":\"Central Park Advanced Imaging \\u2014 Manhattan\",\"notes\":\"Insurance/pricing page links the procedure menu as cash-pay pricing. Radiologist reports described, but separate reading/facility-fee inclusion is not itemized; obtain all-in confirmation. Exact region and base-scan contrast scope need confirmation. Referral language conflicts: MRI FAQ says most scans do not require referral; general pricing page says some programs require one and clinical team can coordinate evaluation/order. Payment at service unless payment plan arranged beforehand; cards and HSA/FSA accepted. No uninsured-only limitation stated. Whole-body price conflicts ($2,000 pricing page versus $2,500 MRI menu), so omitted. Current pages undated; checked October 19, 2026.\",\"other\":\"Ultrasound offered; no amount on reviewed service page\",\"row\":\"162\",\"source\":\"https://cpaimaging.com/services/mri-imaging/\",\"states\":\"NY\"}"},{"content_hash":"a99dc9fefcbc88c45c412f0ffd9fa6afd6076f0c59a7c79b796b73b940e9b79b","entry_key":"cbe0d054a658b54d9641556a99c4eeb72badc35e5d01919ccd4aac693ea1b7c8","payload":"{\"additional\":\"https://proscanbuffalo.com/contact.html\",\"area\":\"Williamsville / Buffalo area\",\"category\":\"Published fixed\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"5214 Main Street, Williamsville, NY 14221\",\"ct\":\"Not offered on reviewed site\",\"entity\":\"Direct operator\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Canadian-patient offer: single MRI not requiring IV contrast $535 USD per scan; single MRI requiring IV contrast $635 USD per scan\",\"name\":\"ProScan Imaging Buffalo \\u2014 Canadian-patient MRI offer\",\"notes\":\"IMPORTANT: Published discount explicitly applies to Canadian patients; do not present as a general U.S.-resident cash rate. Single-scan prices; 'requiring IV contrast' does not establish a with-and-without protocol. Page offers complimentary radiologist consultation, image CD and report within 48 hours, but does not separately itemize facility/read inclusion or contrast-material charges in price. Canadian-patient page says no physician requisition/prescription required. Payment timing, methods and whether insured Canadians qualify are not specified; confirm directly. Official undated offer and contact page checked October 19, 2026.\",\"other\":\"Not listed\",\"row\":\"163\",\"source\":\"https://proscanbuffalo.com/canadian-patients.html\",\"states\":\"NY\"}"},{"content_hash":"387c74575d43bbc241390b0cff571cf9e6f2707f1387723d58bf436ae4e51015","entry_key":"3d3a7f9a7881acbbcd083bc7fea1e7201b9e8d6524b6e02a69d46b2ca723d1ec","payload":"{\"additional\":\"https://mason-imaging.com/services/mri-scans/\\nhttps://mason-imaging.com/services/ct-scan/\\nhttps://mason-imaging.com/book-appointment/\",\"area\":\"Katy\",\"category\":\"Conflicting prices\\u2014quote required\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"2630 N. Mason Road, Suite A1, Katy, TX 77449; 281-914-4465. MRI, CT and digital X-ray are site-confirmed.\",\"ct\":\"Pricing page: without-contrast CT from $200; CT service-page title advertises $125. Exact quote required.\",\"entity\":\"Independent outpatient imaging center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Pricing page: without-contrast MRI from $300; MRI service page still says around $250 starting price. Exact quote required.\",\"name\":\"Mason Imaging \\u2014 Katy\",\"notes\":\"Current linked pricing table and service pages disagree on MRI/CT starting figures; do not treat any as a fixed exam total. Pricing table labels all three modalities as starting prices. MRI/CT figures exclude contrast by description; contrast charges, radiologist interpretation, facility fee, sedation and labs are not itemized. Specific self-pay eligibility, payment timing and clinician-order rules are not clearly stated. Confirm exact ordered exam and all-in total directly before booking. No price-effective date shown. Checked October 19, 2026.\",\"other\":\"Single-view digital X-ray from $40 on pricing page; additional views/exams require a quote\",\"row\":\"164\",\"source\":\"https://mason-imaging.com/price-table/\",\"states\":\"TX\"}"},{"content_hash":"b5783d536673ef567e0d60c7067d3de735316d6dbc7e0e02950bb93c5ce3ed6c","entry_key":"d038366444b6e2354c57575d9800a5298ef3952ba282b220f5b78d851fa60017","payload":"{\"additional\":\"https://mana.md/choose-your-mri-facility/\\nhttps://mana.md/mana-3-tesla-mri-frequently-asked-questions/\\nhttps://mana.md/clinics/fayetteville-imaging-mri-2/\\nhttps://mana.md/clinics/\",\"area\":\"Fayetteville\",\"category\":\"Quote required\",\"checked\":\"2026-10-19 00:00:00\",\"coverage\":\"3383 N. MANA Court, Suite 102, Fayetteville, AR 72703; scheduling 479-684-3900; clinic 479-571-6565\",\"ct\":\"Not at this MRI address; MANA lists CT separately at 3344 N. Futrall Drive\",\"entity\":\"Physician-owned outpatient MRI center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Uninsured self-pay quote required; 3T MRI. Contrast may be billed separately after the scan, up to $200 depending on quantity.\",\"name\":\"MANA 3T MRI \\u2014 Fayetteville\",\"notes\":\"Official MRI material says the advance bill includes scan and radiologist interpretation, with no facility fee. Payment due at service. Contrast is an additional post-exam charge up to $200. Exact MRI base dollar rates are unpublished. The FAQ limits the low self-pay rate to uninsured patients; insured patients cannot elect that rate under its stated contracts. Physician referral/order is the stated scheduling path. Sedation and labs are not expressly included. Current clinic and directory pages verify the address; earlier cost article and indexed official FAQ supply detailed eligibility/billing terms, which should be reconfirmed. Checked October 19, 2026.\",\"other\":\"No other imaging modality established at this MRI address\",\"row\":\"165\",\"source\":\"https://mana.md/clinics/mri/\",\"states\":\"AR\"}"},{"content_hash":"9c9ed9fd0f1b9726c27292e9e75d1a4a89c1052b77745cc472caf6ed215b5831","entry_key":"db9c9cb5b0bcff8786e2ee08d7bc2583af5233e4d0c53205232f650026bc9328","payload":"{\"additional\":\"https://clarusimaging.com/about/\\nhttps://clarusimaging.com/orders/\",\"area\":\"Bloomington\",\"category\":\"Published fixed\",\"checked\":\"2026-10-20 00:00:00\",\"coverage\":\"639 S. Walker St., Suite B, Bloomington, IN 47403; 812-551-1994\",\"ct\":\"Not listed\",\"entity\":\"Independent outpatient MRI center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"$490 noncontrast MRI; confirm ordered brain, spine or joint study\",\"name\":\"Clarus Imaging \\u2014 Bloomington\",\"notes\":\"Includes MRI exam, radiologist interpretation and report to ordering provider. Payment due at scan; card, cash, HSA/FSA and CareCredit listed. Noncontrast studies only. Provider order reviewed before scheduling; confirm exact study and price. No published contrast offer. No rate effective date stated; checked October 20, 2026.\",\"other\":\"Not listed\",\"row\":\"166\",\"source\":\"https://clarusimaging.com/pricing/\",\"states\":\"IN\"}"},{"content_hash":"41c1dd05785487268619293bb250676bd34b5acdaec659e27898bd40e59305f0","entry_key":"268ed1145a97eab6e218927ae8200cd7645cc0fbe38f9f02a9feb7c52a67b87d","payload":"{\"additional\":\"https://www.atlantaboneandjoint.com/self-pay-mri.html\",\"area\":\"Snellville\",\"category\":\"Published fixed\",\"checked\":\"2026-10-20 00:00:00\",\"coverage\":\"2400 Wisteria Drive SW, Suite A, Snellville, GA 30078\",\"ct\":\"Not established for this offer\",\"entity\":\"Orthopedic-practice imaging\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Noncontrast extremity: $400 scan + $75 reading = $475. Noncontrast cervical, thoracic or lumbar spine: $450 + $75 reading = $525.\",\"name\":\"Atlanta Bone & Joint Specialists \\u2014 Snellville MRI\",\"notes\":\"Totals calculated from published scan and mandatory interpretation fees. Snellville office only; requested study must be approved before scheduling. Self-pay pathway does not obtain insurance authorization. No IV-contrast studies via this pathway; contrast considered only for established patients when appropriate. Breast, prostate, cardiac and ENT MRI excluded. Confirm any separate visit or other charge and order requirements. No rate effective date stated; checked October 20, 2026.\",\"other\":\"Not established for this offer\",\"row\":\"167\",\"source\":\"https://www.atlantaboneandjoint.com/self-pay-mri.html\",\"states\":\"GA\"}"},{"content_hash":"ce982491cf5547180efbdf95a274f4b57138d7d82cececde0123f01bd4f37eba","entry_key":"8c62abd8622dd46953da4a0c3529d909b182ae87b1e386b34601bbbf2c936a13","payload":"{\"additional\":\"https://www.grangermedical.com/services/lab-imaging/\",\"area\":\"West Jordan\",\"category\":\"Published fixed\",\"checked\":\"2026-10-20 00:00:00\",\"coverage\":\"3181 W. 9000 S., West Jordan, UT 84088; imaging scheduling 801-965-3435; main 801-569-5600\",\"ct\":\"$325 noncontrast; $350 contrast. Confirm body region and exact protocol.\",\"entity\":\"Multispecialty clinic with outpatient imaging\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"$500 noncontrast; $600 contrast. With-only versus without-and-with protocol not separately defined.\",\"name\":\"Granger Medical Clinic \\u2014 West Jordan, Building A\",\"notes\":\"Location page itself lists MRI/CT prices and verifies onsite CT, MRI, ultrasound and X-ray. Interpretation, contrast supplies, labs, sedation, body-region count, payment timing and eligibility restrictions are not explicitly itemized; obtain an all-in quote. Outside-provider restriction on general lab/imaging page explicitly concerns lab orders, not a confirmed imaging restriction. Do not extend MRI/CT availability to other Granger locations. No rate effective date stated; checked October 20, 2026.\",\"other\":\"Ultrasound and X-ray available; site-specific self-pay amounts not published\",\"row\":\"168\",\"source\":\"https://www.grangermedical.com/locations/west-jordan-clinic-bldg-a/\",\"states\":\"UT\"}"},{"content_hash":"c7fa76121f9ed85de2650bc8d52a749081094b6357d046edc60e948824f25eb8","entry_key":"f9657bfe3fa2bff16f5e061487eda958882287967a7f3f730c12354005f8797a","payload":"{\"additional\":\"https://decaturdiagnosticimaging.com/\",\"area\":\"Decatur\",\"category\":\"From price\",\"checked\":\"2026-10-20 00:00:00\",\"coverage\":\"1201 13th Ave SE, Decatur, AL 35601; 256-350-7779\",\"ct\":\"Not listed\",\"entity\":\"Outpatient imaging center\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"Brain/spine MRI from $400, expressly an estimate. Pricing page also shows $400\\u2013$400; exact contrast/protocol total requires quote.\",\"name\":\"Decatur Diagnostic Imaging\",\"notes\":\"Official pages confirm 1.5T MRI, diagnostic ultrasound and digital X-ray. Doctor referral required. Rates are estimates, not guaranteed all-in charges. Confirm body part, contrast, radiologist fee, other inclusions, payment timing and self-pay eligibility. Website comparative savings claims are not independently verified or adopted here. No rate effective date stated; checked October 20, 2026.\",\"other\":\"Published estimates: ultrasound $150\\u2013$350; X-ray $75\\u2013$150. Homepage examples: abdominal ultrasound from $275; chest/extremity X-ray from $100.\",\"row\":\"169\",\"source\":\"https://decaturdiagnosticimaging.com/pricing\",\"states\":\"AL\"}"},{"content_hash":"fa38d9965a542a29d22567dd51878eb58d48a068ea97f81e97f12ca7cb4b4473","entry_key":"d761e705ff726069aa4bafaefe73d895a7e4a5218732fa702bafe87bf85c250d","payload":"{\"additional\":\"https://www.topekahospital.com/outpatient-services/\",\"area\":\"Topeka\",\"category\":\"Published fixed\",\"checked\":\"2026-10-21 00:00:00\",\"coverage\":\"6135 SW 17th St, Topeka, KS 66615; 785-670-6760\",\"ct\":\"375 without contrast; 550 with contrast; 650 with and without contrast, each one body part\",\"entity\":\"Hospital outpatient imaging\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"525 without contrast, one body part; 700 with and without contrast (IV included)\",\"name\":\"Topeka ER & Hospital \\u2014 outpatient imaging\",\"notes\":\"Physician outpatient order required; MRI Monday\\u2013Thursday. CT contrast prices include IV and labs if needed. MRA contrast if ordered. Radiologist/facility fee inclusion not explicitly stated: confirm total. Page also lists contrast-only MRI 350 requiring radiologist approval; not interchangeable with the 525 or 700 protocols. No price effective date published; checked 2026-10-21. Outpatient cash menu, not emergency-visit price.\",\"other\":\"X-ray extremity/joint 2\\u20133 views 120; chest 1 view 120 / 2 views 150; ultrasound any body part 325; MRA one body part 600\",\"row\":\"170\",\"source\":\"https://www.topekahospital.com/cash-pricing/\",\"states\":\"KS\"}"},{"content_hash":"576879e02be82f85a0d40e9e4063ad0f15fe30cc3b2cebd4f2762bcf79e57a71","entry_key":"f6a0867e8c619f931e786d0d1c3eda87103f10f8fc85bcd908c6127de52eaa87","payload":"{\"additional\":\"https://okerhospital.com/outpatient-services/\",\"area\":\"Edmond\",\"category\":\"Published fixed\",\"checked\":\"2026-10-21 00:00:00\",\"coverage\":\"15103 N. Pennsylvania Avenue, Edmond, OK 73013; 405-251-2300\",\"ct\":\"275 without contrast; 375 with contrast (labs and IV included); CT angiogram 425 (labs and IV included)\",\"entity\":\"Hospital outpatient imaging\",\"location_type\":\"unresolved\",\"locations\":[],\"mri\":\"399 without contrast; 499 with contrast (labs and IV included)\",\"name\":\"Oklahoma ER & Hospital \\u2014 outpatient imaging\",\"notes\":\"Physician outpatient order required; MRI Monday\\u2013Friday. Published prices are for the listed body-part/protocol, not whole-body imaging. With-contrast wording does not establish a with-and-without protocol. Radiologist/facility fee inclusion not explicitly stated: confirm total. No price effective date published; checked 2026-10-21. Direct outpatient cash menu, not emergency-visit or third-party voucher pricing.\",\"other\":\"X-ray extremity/joint 2\\u20133 views 75; 4 views 100; chest 1 view 115 / 2 views 150; ultrasound any body part 300; pregnancy ultrasound with labs 450\",\"row\":\"171\",\"source\":\"https://okerhospital.com/cash-pricing/\",\"states\":\"OK\"}"},{"content_hash":"470f029ee615b530004f8d57f8c2d2629941002c79d0d57dec64c5d798f05dc2","entry_key":"1b5fbfe42af1ef6d02cec7309eb779d576c113bbcec64236bdf4c0831ed0290d","payload":"{\"additional\":\"\",\"area\":\"Chandler\",\"category\":\"Published fixed\",\"checked\":\"2026-10-22 00:00:00\",\"coverage\":\"3050 S Dobson Rd, Chandler, AZ 85248; 480-284-5867\",\"ct\":\"200 withou